package main

import (
 "fmt"
 "go/ast"
 "go/importer"
 "go/parser"
 "go/token"
 "go/types"
 "os"
)

const src = `package p
import "example/ext"
`
func main(){
 _ = src; _ = os.Args; _ = importer.Default
 fset:=token.NewFileSet()
 files:=[]*ast.File{}
 for _, path := range os.Args[1:] {
   f, err:=parser.ParseFile(fset, path, nil, 0)
   if err!=nil{panic(err)}
   files=append(files,f)
 }
 info:=&types.Info{Types:make(map[ast.Expr]types.TypeAndValue), Defs:make(map[*ast.Ident]types.Object), Uses:make(map[*ast.Ident]types.Object), Selections:make(map[*ast.SelectorExpr]*types.Selection)}
 conf:=types.Config{Importer: importer.Default()}
 pkg, err:=conf.Check("example.com/p", fset, files, info)
 fmt.Println("pkg",pkg,err)
 for sel, s := range info.Selections {
   fmt.Printf("SEL %s.%s kind=%s recv=%s obj=%q objpkg=%v ind=%v\n", fset.Position(sel.Pos()), sel.Sel.Name, s.Kind(), s.Recv(), s.Obj(), s.Obj().Pkg(), s.Index())
 }
 for id, obj := range info.Uses {
   if _, ok:=obj.(*types.Func); ok {
      fmt.Printf("USEFUNC %s %s => %q pkg=%v\n", fset.Position(id.Pos()), id.Name, obj, obj.Pkg())
   }
 }
 for expr, tv := range info.Types {
   if ce, ok:=expr.(*ast.CallExpr); ok {
     fmt.Printf("CALL %s type=%q str=%s fun=%T\n", fset.Position(ce.Pos()), tv.Type, tv.Type.String(), ce.Fun)
   }
 }
}
EOF
