func B() error { s:=S{}; return s.M() }
func C(h H) error { return h.F() }
func D() error { return errors.New("x") }
func E() error { return GV("x") }
func F() error { return fmt.Errorf("x") }
func G() (int,error) { return fmt.Errorf("x"), nil }
func H2() error { return I.M(nil) }
func I2() error { return S.M(S{}) }
EOF
cd /tmp/typesproto && go run . testpkg/a.go 2>&1 | sort"}

