package main

import (
 "encoding/json"
 "fmt"
 "go/ast"
 "go/importer"
 "go/parser"
 "go/token"
 "go/types"
 "io"
 "os"
 "os/exec"
 "path/filepath"
 "strings"
)
type LP struct { Dir string; ImportPath string; Export string }
func main(){
 cwd:=os.Args[1]; pattern:=os.Args[2]
 cmd:=exec.Command("go","list","-e","-json","-test=true","-compiled=true","-export=true","-deps=true","--",pattern)
 cmd.Dir=cwd
 out, err:=cmd.Output(); if err!=nil{panic(err)}
 dec:=json.NewDecoder(strings.NewReader(string(out)))
 byPath:=map[string]*LP{}
 for dec.More(){ var lp LP; if err:=dec.Decode(&lp); err!=nil{panic(err)}; byPath[lp.ImportPath]=&lp }
 fmt.Println("packages",len(byPath))
 fset:=token.NewFileSet()
 imp:=importer.ForCompiler(fset, "gc", func(path string)(io.ReadCloser,error){
   lp,ok:=byPath[path]; if !ok || lp.Export=="" { return nil, fmt.Errorf("no export for %s",path)}
   fmt.Println("lookup",path,lp.Export)
   return os.Open(lp.Export)
 })
 // parse target files from cwd
 files:=[]*ast.File{}
 entries,_:=os.ReadDir(cwd)
 for _,e:=range entries { if strings.HasSuffix(e.Name(),".go") { f,err:=parser.ParseFile(fset, filepath.Join(cwd,e.Name()),nil,parser.ParseComments); if err!=nil{panic(err)}; files=append(files,f)}}
 info:=&types.Info{Types:map[ast.Expr]types.TypeAndValue{},Defs:map[*ast.Ident]types.Object{},Uses:map[*ast.Ident]types.Object{},Selections:map[*ast.SelectorExpr]*types.Selection{}}
 conf:=types.Config{Importer:imp, FakeImportC:true, Error: func(err error){fmt.Println("typeerr",err)}}
 pkg,err:=conf.Check("example.com/wtest1",fset,files,info)
 fmt.Println("checked",pkg,err)
 for sel,s:=range info.Selections{ fmt.Println("sel",sel.Sel.Name,s.Obj())}
 for e,tv:=range info.Types{ if c,ok:=e.(*ast.CallExpr); ok { fmt.Println("call",c.Pos(),tv.Type)}}
}
EOF
cd /tmp/protoimp && go mod init protoimp >/dev/null 2>&1; go run . /tmp/wtest1 . 2>&1 | head -100"}

