// Minimal YAML representation used only for the simple configuration
// files understood by this tool.
type yamlKind int

const (
	yamlNull yamlKind = iota
	yamlString
	yamlBool
	yamlNumber
	yamlList
	yamlMap
)

type yamlValue struct {
	kind yamlKind
	str  string
	b    bool
	list []*yamlValue
	keys []string
	m    map[string]*yamlValue
	line int
}

func yamlNullValue(line int) *yamlValue { return &yamlValue{kind: yamlNull, line: line} }

type yamlParser struct {
	lines []yamlLine
	pos   int
}

type yamlLine struct {
	text   string
	raw    string
	indent int
	num    int
	blank  bool
}

func splitYAMLLine(raw string, num int) yamlLine {
	if strings.TrimSpace(raw) == "" {
		return yamlLine{raw: raw, num: num, blank: true}
	}
	trimmedLeft := strings.TrimLeft(raw, " ")
	indent := len(raw) - len(trimmedLeft)
	return yamlLine{text: strings.TrimRight(trimmedLeft, " \t\r"), raw: raw, indent: indent, num: num}
}

func stripYAMLComment(s string) string {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				if i == 0 || s[i-1] != '\\' {
					inDouble = !inDouble
				}
			}
		case '#':
			if !inSingle && !inDouble && i > 0 && (s[i-1] == ' ' || s[i-1] == '\t') {
				return strings.TrimRight(s[:i], " \t")
			}
		}
	}
	return s
}

func parseYAMLScalarToken(tok string, line int) (*yamlValue, error) {
	tok = strings.TrimSpace(tok)
	if tok == "" || tok == "~" || strings.EqualFold(tok, "null") {
		return yamlNullValue(line), nil
	}
	tok = stripYAMLComment(tok)
	tok = strings.TrimSpace(tok)
	if tok == "" {
		return yamlNullValue(line), nil
	}
	if strings.HasPrefix(tok, "'") {
		if len(tok) < 2 || !strings.HasSuffix(tok, "'") {
			return nil, fmt.Errorf("yaml: line %d: found unexpected end of stream", line)
		}
		inner := tok[1 : len(tok)-1]
		inner = strings.ReplaceAll(inner, "''", "'")
		return &yamlValue{kind: yamlString, str: inner, line: line}, nil
	}
	if strings.HasPrefix(tok, "\"") {
		uq, err := strconv.Unquote(tok)
		if err != nil {
			return nil, fmt.Errorf("yaml: line %d: found unknown escape character", line)
		}
		return &yamlValue{kind: yamlString, str: uq, line: line}, nil
	}
	switch tok {
	case "true", "True", "TRUE":
		return &yamlValue{kind: yamlBool, b: true, str: tok, line: line}, nil
	case "false", "False", "FALSE":
		return &yamlValue{kind: yamlBool, b: false, str: tok, line: line}, nil
	}
	// A plain non-empty scalar that contains no mapping indicator is a
	// string unless it is a plain number.
	if _, err := strconv.ParseFloat(tok, 64); err == nil {
		return &yamlValue{kind: yamlNumber, str: tok, line: line}, nil
	}
	return &yamlValue{kind: yamlString, str: tok, line: line}, nil
}

func splitFlowItems(s string, line int) ([]string, error) {
	var items []string
	depth := 0
	inSingle, inDouble := false, false
	start := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case '[', '{':
			if !inSingle && !inDouble {
				depth++
			}
		case ']', '}':
			if !inSingle && !inDouble {
				depth--
			}
		case ',':
			if !inSingle && !inDouble && depth == 0 {
				items = append(items, strings.TrimSpace(s[start:i]))
				start = i + 1
			}
		}
	}
	if inSingle || inDouble || depth != 0 {
		return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or ']'", line)
	}
	if strings.TrimSpace(s[start:]) != "" {
		items = append(items, strings.TrimSpace(s[start:]))
	}
	return items, nil
}

func (p *yamlParser) parseFlowValue(tok string, line int) (*yamlValue, error) {
	tok = strings.TrimSpace(tok)
	if strings.HasPrefix(tok, "[") {
		if !strings.HasSuffix(tok, "]") {
			return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or ']'", line)
		}
		inner := strings.TrimSpace(tok[1 : len(tok)-1])
		v := &yamlValue{kind: yamlList, line: line}
		if inner == "" {
			return v, nil
		}
		items, err := splitFlowItems(inner, line)
		if err != nil {
			return nil, err
		}
		for _, item := range items {
			iv, err := p.parseInlineValue(item, line)
			if err != nil {
				return nil, err
			}
			v.list = append(v.list, iv)
		}
		return v, nil
	}
	if strings.HasPrefix(tok, "{") {
		if !strings.HasSuffix(tok, "}") {
			return nil, fmt.Errorf("yaml: line %d: did not find expected ',' or '}'", line)
		}
		inner := strings.TrimSpace(tok[1 : len(tok)-1])
		v := &yamlValue{kind: yamlMap, m: map[string]*yamlValue{}, line: line}
		if inner == "" {
			return v, nil
		}
		items, err := splitFlowItems(inner, line)
		if err != nil {
			return nil, err
		}
		for _, item := range items {
			k, val, found := splitYAMLKey(item)
			if !found {
				return nil, fmt.Errorf("yaml: line %d: could not find expected ':'", line)
			}
			iv, err := p.parseInlineValue(val, line)
			if err != nil {
				return nil, err
			}
			k = strings.TrimSpace(k)
			v.keys = append(v.keys, k)
			v.m[k] = iv
		}
		return v, nil
	}
	return parseYAMLScalarToken(tok, line)
}

func (p *yamlParser) parseInlineValue(tok string, line int) (*yamlValue, error) {
	tok = strings.TrimSpace(stripYAMLComment(tok))
	if strings.HasPrefix(tok, "[") || strings.HasPrefix(tok, "{") {
		return p.parseFlowValue(tok, line)
	}
	return parseYAMLScalarToken(tok, line)
}

func splitYAMLKey(s string) (string, string, bool) {
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\'':
			if !inDouble {
				inSingle = !inSingle
			}
		case '"':
			if !inSingle {
				inDouble = !inDouble
			}
		case ':':
			if !inSingle && !inDouble {
				if i == len(s)-1 {
					return s[:i], "", true
				}
				if s[i+1] == ' ' || s[i+1] == '\t' {
					return s[:i], strings.TrimSpace(s[i+1:]), true
				}
			}
		}
	}
	return "", "", false
}

func parseYAMLKeyToken(tok string, line int) (string, error) {
	tok = strings.TrimSpace(tok)
	if tok == "" {
		return "", fmt.Errorf("yaml: line %d: could not find expected ':'", line)
	}
	v, err := parseYAMLScalarToken(tok, line)
	if err != nil {
		return "", err
	}
	if v.kind == yamlNull {
		return "", nil
	}
	return v.str, nil
}

// parse next significant line index, or -1.
func (p *yamlParser) nextSignificant(from int) int {
	for i := from; i < len(p.lines); i++ {
		l := p.lines[i]
		if l.blank {
			continue
		}
		t := strings.TrimSpace(l.text)
		if strings.HasPrefix(t, "#") {
			continue
		}
		if t == "---" || t == "..." {
			continue
		}
		return i
	}
	return -1
}

func (p *yamlParser) parseDocument() (*yamlValue, error) {
	idx := p.nextSignificant(0)
	if idx == -1 {
		return &yamlValue{kind: yamlMap, m: map[string]*yamlValue{}}, nil
	}
	first := p.lines[idx]
	text := strings.TrimSpace(first.text)
	if strings.HasPrefix(text, "- ") || text == "-" {
		// A top level sequence is not a config mapping.
		return nil, fmt.Errorf("yaml: unmarshal errors:\n  line %d: cannot unmarshal !!seq into map[string]interface {}", first.num)
	}
	if _, _, found := splitYAMLKey(text); !found {
		// A bare scalar document.
		tok := text
		if len(tok) > 10 {
			tok = tok[:7] + "..."
		}
		return nil, fmt.Errorf("yaml: unmarshal errors:\n  line %d: cannot unmarshal !!str `%s` into map[string]interface {}", first.num, tok)
	}
	p.pos = idx
	return p.parseMapping(first.indent)
}

func (p *yamlParser) parseMapping(indent int) (*yamlValue, error) {
	out := &yamlValue{kind: yamlMap, m: map[string]*yamlValue{}}
	for p.pos < len(p.lines) {
		idx := p.nextSignificant(p.pos)
		if idx == -1 {
			p.pos = len(p.lines)
			break
		}
		ln := p.lines[idx]
		if ln.indent < indent {
			p.pos = idx
			break
		}
		if ln.indent > indent {
			return nil, fmt.Errorf("yaml: line %d: mapping values are not allowed in this context", ln.num)
		}
		text := ln.text
		if strings.HasPrefix(text, "- ") || text == "-" {
			// belongs to caller
			p.pos = idx
			break
		}
		if strings.Contains(ln.raw, "\t") && ln.indent == 0 && strings.HasPrefix(ln.raw, "\t") {
			return nil, fmt.Errorf("yaml: line %d: found character '\\t' that cannot start any token", ln.num)
		}
		keyTok, valTok, found := splitYAMLKey(text)
		if !found {
			return nil, fmt.Errorf("yaml: line %d: could not find expected ':'", ln.num)
		}
		key, err := parseYAMLKeyToken(keyTok, ln.num)
		if err != nil {
			return nil, err
		}
		p.pos = idx + 1
		var val *yamlValue
		valTokTrim := strings.TrimSpace(stripYAMLComment(valTok))
		if valTokTrim != "" {
			val, err = p.parseInlineValue(valTokTrim, ln.num)
			if err != nil {
				return nil, err
			}
			// Block scalars.
			if valTokTrim == "|" || valTokTrim == ">" || valTokTrim == "|-" || valTokTrim == ">-" || valTokTrim == "|+" || valTokTrim == ">+" {
				var parts []string
				for p.pos < len(p.lines) {
					nidx := p.nextSignificant(p.pos)
					if nidx == -1 {
						p.pos = len(p.lines)
						break
					}
					nl := p.lines[nidx]
					if nl.indent <= indent {
						break
					}
					parts = append(parts, strings.TrimSpace(nl.text))
					p.pos = nidx + 1
				}
				sep := "\n"
				if strings.HasPrefix(valTokTrim, ">") {
					sep = " "
				}
				val = &yamlValue{kind: yamlString, str: strings.Join(parts, sep), line: ln.num}
			}
		} else {
			// Look ahead for a block sequence or a nested mapping.
			nidx := p.nextSignificant(p.pos)
			if nidx == -1 {
				val = yamlNullValue(ln.num)
				p.pos = len(p.lines)
			} else {
				nl := p.lines[nidx]
				ntext := strings.TrimSpace(nl.text)
				if (strings.HasPrefix(ntext, "- ") || ntext == "-") && nl.indent >= indent {
					p.pos = nidx
					val, err = p.parseSequence(nl.indent)
					if err != nil {
						return nil, err
					}
				} else if nl.indent > indent {
					p.pos = nidx
					val, err = p.parseMapping(nl.indent)
					if err != nil {
						return nil, err
					}
				} else {
					val = yamlNullValue(ln.num)
				}
			}
		}
		if _, exists := out.m[key]; !exists {
			out.keys = append(out.keys, key)
		}
		out.m[key] = val
	}
	return out, nil
}

func (p *yamlParser) parseSequence(indent int) (*yamlValue, error) {
	out := &yamlValue{kind: yamlList}
	for p.pos < len(p.lines) {
		idx := p.nextSignificant(p.pos)
		if idx == -1 {
			p.pos = len(p.lines)
			break
		}
		ln := p.lines[idx]
		if ln.indent != indent {
			if ln.indent < indent {
				p.pos = idx
				break
			}
			return nil, fmt.Errorf("yaml: line %d: block sequence entries are not allowed in this context", ln.num)
		}
		text := ln.text
		if !(strings.HasPrefix(text, "- ") || text == "-") {
			p.pos = idx
			break
		}
		itemText := strings.TrimSpace(strings.TrimPrefix(text, "-"))
		p.pos = idx + 1
		itemText = strings.TrimSpace(stripYAMLComment(itemText))
		if itemText == "" {
			out.list = append(out.list, yamlNullValue(ln.num))
			continue
		}
		// An inline mapping inside a sequence item is represented as a
		// map; the configuration fields never use this for scalars.
		if _, _, found := splitYAMLKey(itemText); found && !strings.HasPrefix(itemText, "\"") && !strings.HasPrefix(itemText, "'") {
			m := &yamlValue{kind: yamlMap, m: map[string]*yamlValue{}, line: ln.num}
			k, v, _ := splitYAMLKey(itemText)
			key, err := parseYAMLKeyToken(k, ln.num)
			if err != nil {
				return nil, err
			}
			iv, err := p.parseInlineValue(v, ln.num)
			if err != nil {
				return nil, err
			}
			m.keys = append(m.keys, key)
			m.m[key] = iv
			out.list = append(out.list, m)
			continue
		}
		iv, err := p.parseInlineValue(itemText, ln.num)
		if err != nil {
			return nil, err
		}
		out.list = append(out.list, iv)
	}
	return out, nil
}

func parseYAMLConfig(data []byte) (*yamlValue, error) {
	content := string(data)
	content = strings.TrimPrefix(content, "\ufeff")
	rawLines := strings.Split(content, "\n")
	p := &yamlParser{}
	for i, rl := range rawLines {
		rl = strings.TrimSuffix(rl, "\r")
		p.lines = append(p.lines, splitYAMLLine(rl, i+1))
	}
	return p.parseDocument()
}

func yamlScalarString(v *yamlValue) string {
	if v == nil {
		return ""
	}
	switch v.kind {
	case yamlString, yamlNumber:
		return v.str
	case yamlBool:
		if v.b {
			return "true"
		}
		return "false"
	default:
		return ""
	}
}

func configUnmarshalError(msg string) {
	log.Fatalf("failed to unmarshal config: %s", msg)
}

func applyConfigValue(cfg *Config, key string, v *yamlValue) {
	if v == nil || v.kind == yamlNull {
		return
	}
	lower := strings.ToLower(key)
	var sliceTarget *[]string
	switch lower {
	case "ignoresigs":
		sliceTarget = &cfg.IgnoreSigs
	case "extraignoresigs":
		sliceTarget = &cfg.ExtraIgnoreSigs
	case "ignoresigregexps":
		sliceTarget = &cfg.IgnoreSigRegexps
	case "ignorepackageglobs":
		sliceTarget = &cfg.IgnorePackageGlobs
	case "ignoreinterfaceregexps":
		sliceTarget = &cfg.IgnoreInterfaceRegexps
	case "reportinternalerrors":
		switch v.kind {
		case yamlBool:
			cfg.ReportInternalErrors = v.b
		case yamlString:
			parsed, err := strconv.ParseBool(v.str)
			if err != nil {
				configUnmarshalError(fmt.Sprintf("1 error(s) decoding:\n\n* cannot parse 'reportInternalErrors' as bool: strconv.ParseBool: parsing %q: invalid syntax", v.str))
			}
			cfg.ReportInternalErrors = parsed
		case yamlNumber:
			f, err := strconv.ParseFloat(v.str, 64)
			if err != nil {
				configUnmarshalError(fmt.Sprintf("1 error(s) decoding:\n\n* cannot parse 'reportInternalErrors' as bool: strconv.ParseBool: parsing %q: invalid syntax", v.str))
			}
			cfg.ReportInternalErrors = f != 0
		default:
			configUnmarshalError(fmt.Sprintf("1 error(s) decoding:\n\n* cannot parse 'reportInternalErrors' as bool: strconv.ParseBool: parsing %q: invalid syntax", yamlScalarString(v)))
		}
		return
	default:
		return
	}
	if sliceTarget == nil {
		return
	}
	switch v.kind {
	case yamlList:
		out := make([]string, 0, len(v.list))
		for _, item := range v.list {
			out = append(out, yamlScalarString(item))
		}
		*sliceTarget = out
	case yamlString, yamlNumber, yamlBool:
		s := yamlScalarString(v)
		if s == "" {
			*sliceTarget = []string{}
		} else {
			*sliceTarget = []string{s}
		}
	case yamlMap:
		configUnmarshalError(fmt.Sprintf("1 error(s) decoding:\n\n* '%s' source data must be array or slice, got map", key))
	}
}

func findConfigFile() (string, bool) {
	exts := []string{"json", "toml", "yaml", "yml", "properties", "props", "prop", "hcl", "tfvars", "dotenv", "env", "ini"}
	candidates := make([]string, 0, len(exts)+1)
	for _, ext := range exts {
		candidates = append(candidates, ".wrapcheck."+ext)
	}
	candidates = append(candidates, ".wrapcheck")
	for _, name := range candidates {
		info, err := os.Stat(name)
		if err == nil && !info.IsDir() {
			return name, true
		}
	}
	return "", false
}

func loadConfig() *Config {
	cfg := defaultConfig()
	path, ok := findConfigFile()
	if !ok {
		return cfg
	}
	data, err := os.ReadFile(path)
	if err != nil {
		log.Fatalf("failed to parse config: %s", err)
	}
	root, err := parseYAMLConfig(data)
	if err != nil {
		log.Fatalf("failed to parse config: While parsing config: %s", err)
	}
	if root != nil && root.kind == yamlMap {
		for _, key := range root.keys {
			applyConfigValue(cfg, key, root.m[key])
		}
	}
	if len(cfg.ExtraIgnoreSigs) > 0 {
		cfg.IgnoreSigs = append(cfg.IgnoreSigs, cfg.ExtraIgnoreSigs...)
	}
	return cfg
}

// ---------------- glob matching ----------------

type globMatcher struct {
	re *regexp.Regexp
}

func globClassError(msg string) error { return errors.New(msg) }

type globParser struct {
	pat string
	i   int
}

func (g *globParser) parseSequence(inBraces bool) (string, error) {
	var sb strings.Builder
	for g.i < len(g.pat) {
		c := g.pat[g.i]
		if inBraces && (c == ',' || c == '}') {
			break
		}
		switch c {
		case '*':
			for g.i < len(g.pat) && g.pat[g.i] == '*' {
				g.i++
			}
			sb.WriteString("(?s:.*)")
		case '?':
			g.i++
			sb.WriteString("(?s:.)")
		case '[':
			cls, err := g.parseClass()
			if err != nil {
				return "", err
			}
			sb.WriteString(cls)
		case '{':
			alt, ok, err := g.parseAlternatives()
			if err != nil {
				return "", err
			}
			if !ok {
				sb.WriteString(regexp.QuoteMeta("{"))
				g.i++
			} else {
				sb.WriteString(alt)
			}
		case '\\':
			g.i++
			if g.i >= len(g.pat) {
				sb.WriteString(regexp.QuoteMeta("\\"))
			} else {
				sb.WriteString(regexp.QuoteMeta(string(g.pat[g.i])))
				g.i++
			}
		default:
			sb.WriteString(regexp.QuoteMeta(string(c)))
			g.i++
		}
	}
	return sb.String(), nil
}

func (g *globParser) parseAlternatives() (string, bool, error) {
	// Verify a closing brace exists at the same nesting level.
	depth := 0
	found := false
	for j := g.i; j < len(g.pat); j++ {
		switch g.pat[j] {
		case '{':
			depth++
		case '}':
			depth--
			if depth == 0 {
				found = true
				j = len(g.pat)
			}
		case '\\':
			j++
		}
		if found {
			break
		}
	}
	if !found {
		return "", false, nil
	}
	g.i++ // consume '{'
	var alts []string
	for {
		part, err := g.parseSequence(true)
		if err != nil {
			return "", false, err
		}
		alts = append(alts, part)
		if g.i >= len(g.pat) {
			return "", false, globClassError("unexpected end of input")
		}
		if g.pat[g.i] == ',' {
			g.i++
			continue
		}
		if g.pat[g.i] == '}' {
			g.i++
			break
		}
		return "", false, globClassError("unexpected end of input")
	}
	return "(?:" + strings.Join(alts, "|") + ")", true, nil
}

func (g *globParser) parseClass() (string, error) {
	// g.pat[g.i] == '['
	start := g.i
	g.i++
	if g.i >= len(g.pat) {
		return "", globClassError("unexpected end of input")
	}
	neg := false
	if g.pat[g.i] == '^' || g.pat[g.i] == '!' {
		// gobwas supports ^ as the negation marker; '!' is accepted
		// as it appears in some glob dialects.
		if g.pat[g.i] == '^' {
			neg = true
			g.i++
			if g.i >= len(g.pat) {
				return "", globClassError("unexpected end of input")
			}
		}
	}
	// Empty non-negated class.
	if !neg && g.i < len(g.pat) && g.pat[g.i] == ']' {
		return "", globClassError("could not parse range")
	}
	if neg && g.i < len(g.pat) && g.pat[g.i] == ']' {
		// [^] is treated as a negated empty class.
		g.i++
		return "(?s:.)", nil
	}
	_ = start
	var elems []string
	first := true
	for {
		if g.i >= len(g.pat) {
			// If the last thing read was a complete range item the
			// error differs from a plain unterminated class.
			return "", globClassError("unexpected end of input")
		}
		if g.pat[g.i] == ']' && !first {
			g.i++
			break
		}
		first = false
		lo, err := g.readClassChar()
		if err != nil {
			return "", err
		}
		if g.i < len(g.pat) && g.pat[g.i] == '-' {
			g.i++
			if g.i >= len(g.pat) {
				return "", globClassError("unexpected end of input")
			}
			if g.pat[g.i] == ']' {
				return "", globClassError("unexpected end of input")
			}
			hi, err := g.readClassChar()
			if err != nil {
				return "", err
			}
			if hi < lo {
				return "", fmt.Errorf("hi character %q should be greater than lo %q", hi, lo)
			}
			if g.i >= len(g.pat) {
				return "", globClassError("expected close range character")
			}
			elems = append(elems, escapeClassRune(lo)+"-"+escapeClassRune(hi))
		} else {
			elems = append(elems, escapeClassRune(lo))
		}
	}
	var sb strings.Builder
	sb.WriteString("[")
	if neg {
		sb.WriteString("^")
	}
	sb.WriteString(strings.Join(elems, ""))
	sb.WriteString("]")
	return sb.String(), nil
}

func (g *globParser) readClassChar() (rune, error) {
	if g.i >= len(g.pat) {
		return 0, globClassError("unexpected end of input")
	}
	if g.pat[g.i] == '\\' {
		g.i++
		if g.i >= len(g.pat) {
			return '\\', nil
		}
		r := rune(g.pat[g.i])
		g.i++
		return r, nil
	}
	r := rune(g.pat[g.i])
	g.i++
	return r, nil
}

func escapeClassRune(r rune) string {
	switch r {
	case '\\', ']', '^', '-':
		return "\\" + string(r)
	default:
		return string(r)
	}
}

func compileGlob(pat string) (*globMatcher, error) {
	g := &globParser{pat: pat}
	expr, err := g.parseSequence(false)
	if err != nil {
		return nil, err
	}
	if g.i < len(g.pat) {
		// Unmatched closing constructs are literal in this dialect.
		rest, err := g.parseSequence(false)
		if err != nil {
			return nil, err
		}
		expr += rest
	}
	re, err := regexp.Compile("^" + expr + "$")
	if err != nil {
		return nil, err
	}
	return &globMatcher{re: re}, nil
}

func (m *globMatcher) Match(s string) bool { return m.re.MatchString(s) }

// ---------------- flags / driver data ----------------

type versionFlag struct {
	value string
	set   bool
}

func (v *versionFlag) String() string { return v.value }
func (v *versionFlag) Set(s string) error {
	v.value = s
	v.set = true
	return nil
}
func (v *versionFlag) IsBoolFlag() bool { return true }

type flagInfo struct {
	Name  string
	Bool  bool
	Usage string
}

var (
	cfgGlobal *Config

	flagVersion    versionFlag
	flagAll        bool
	flagC          int
	flagCPUProfile string
	flagDebug      string
	flagDiff       bool
	flagFix        bool
	flagFlags      bool
	flagJSON       bool
	flagMemProfile string
	flagSource     bool
	flagTags       string
	flagTest       bool
	flagTrace      string
	flagV          bool
)

func printUsage() {
	out := flag.CommandLine.Output()
	fmt.Fprintf(out, "wrapcheck: Checks that errors returned from external packages are wrapped\n\nUsage: wrapcheck [-flag] [package]\n\n\nFlags:\n")
	flag.PrintDefaults()
}

func isBoolFlagValue(v flag.Value) bool {
	if b, ok := v.(interface{ IsBoolFlag() bool }); ok {
		return b.IsBoolFlag()
	}
	return false
}

func printFlagsJSON() {
	names := []string{"V", "all", "c", "diff", "flags", "json", "source", "tags", "test", "v"}
	infos := make([]flagInfo, 0, len(names))
	// VisitAll yields flags in lexicographical order; filtering it
	// reproduces the set of shareable analyzer flags.
	flag.VisitAll(func(f *flag.Flag) {
		for _, want := range names {
			if f.Name == want {
				infos = append(infos, flagInfo{Name: f.Name, Bool: isBoolFlagValue(f.Value), Usage: f.Usage})
			}
		}
	})
	data, _ := json.MarshalIndent(infos, "", "\t")
	os.Stdout.Write(data)
}

// ---------------- package loading ----------------

type goListError struct {
	Pos string
	Err string
}

type listPackage struct {
	Dir             string
	ImportPath      string
	Name            string
	GoFiles         []string
	CgoFiles        []string
	TestGoFiles     []string
	XTestGoFiles    []string
	CompiledGoFiles []string
	Export          string
	Imports         []string
	ImportMap       map[string]string
	ForTest         string
	Incomplete      bool
	Match           []string
	Error           *goListError
	DepsErrors      []*goListError
	index           int
}

type pkgError struct {
	Pos string
	Msg string
}

func (e pkgError) String() string {
	pos := e.Pos
	if pos == "" {
		pos = "-"
	}
	return pos + ": " + strings.TrimRight(e.Msg, "\n")
}

type rootPackage struct {
	lp         *listPackage
	key        string
	typesPath  string
	files      []*ast.File
	info       *types.Info
	typesPkg   *types.Package
	ownErrors  []pkgError
	illTyped   bool
	diagnostics []diagnostic
	actionErr  string
	hasActionErr bool
	elapsed    int64
}

type diagnostic struct {
	pos     token.Pos
	posStr  string
	file    string
	line    int
	message string
}

type loader struct {
	fset       *token.FileSet
	pkgs       []*listPackage
	byPath     map[string]*listPackage
	byClean    map[string]*listPackage
	aliasTo    map[string]string
	importer   *customImporter
	roots      []*rootPackage
	loadErrors []pkgError
	seenLoadErr map[string]bool
}

type customImporter struct {
	fset       *token.FileSet
	loader     *loader
	exportImp  types.Importer
	cache      map[string]*types.Package
	inProgress map[string]bool
}

func (ci *customImporter) lookup(path string) (io.ReadCloser, error) {
	lp := ci.loader.findListPackage(path)
	if lp == nil || lp.Export == "" {
		return nil, fmt.Errorf("no export data for %s", path)
	}
	return os.Open(lp.Export)
}

func (ci *customImporter) Import(path string) (*types.Package, error) {
	if p, ok := ci.cache[path]; ok {
		return p, nil
	}
	if p, err := ci.exportImp.Import(path); err == nil {
		ci.cache[path] = p
		return p, nil
	}
	// Fall back to checking the dependency from source.  This matters
	// for packages whose export data could not be produced (they will
	// be reported through the load-error path instead), and for test
	// variants of packages in the same module.
	lp := ci.loader.findListPackage(path)
	if lp != nil {
		if p := ci.loader.checkDependency(lp, ci); p != nil {
			ci.cache[path] = p
			return p, nil
		}
	}
	// Re-run to obtain a representative error.
	_, err := ci.exportImp.Import(path)
	if err != nil {
		return nil, err
	}
	return nil, fmt.Errorf("could not import %s", path)
}

func (l *loader) findListPackage(path string) *listPackage {
	if lp, ok := l.byPath[path]; ok {
		return lp
	}
	if target, ok := l.aliasTo[path]; ok {
		if lp, ok := l.byPath[target]; ok {
			return lp
		}
	}
	if lp, ok := l.byClean[path]; ok {
		return lp
	}
	// Vendored imports may be keyed by their physical path.
	for _, lp := range l.pkgs {
		if strings.HasSuffix(lp.ImportPath, "/vendor/"+path) {
			return lp
		}
	}
	return nil
}

func cleanImportPath(p string) string {
	if idx := strings.Index(p, " ["); idx >= 0 {
		return p[:idx]
	}
	return p
}

func absJoin(dir, name string) string {
	if filepath.IsAbs(name) {
		return name
	}
	if dir == "" {
		return name
	}
	return filepath.Join(dir, name)
}

func (l *loader) filesFor(lp *listPackage, compiled bool) []string {
	var names []string
	if compiled && len(lp.CompiledGoFiles) > 0 {
		names = lp.CompiledGoFiles
	} else {
		names = append(names, lp.GoFiles...)
		names = append(names, lp.CgoFiles...)
	}
	out := make([]string, 0, len(names))
	for _, n := range names {
		if !strings.HasSuffix(n, ".go") {
			continue
		}
		out = append(out, absJoin(lp.Dir, n))
	}
	return out
}

func (l *loader) parseFiles(filenames []string) ([]*ast.File, []pkgError) {
	var files []*ast.File
	var errs []pkgError
	for _, name := range filenames {
		f, err := parser.ParseFile(l.fset, name, nil, parser.ParseComments|parser.AllErrors)
		if err != nil {
			if el, ok := err.(scanner.ErrorList); ok {
				for _, e := range el {
					errs = append(errs, pkgError{Pos: e.Pos.String(), Msg: e.Msg})
				}
			} else {
				errs = append(errs, pkgError{Pos: name, Msg: err.Error()})
			}
		}
		if f != nil {
			files = append(files, f)
		}
	}
	return files, errs
}

func (l *loader) typesConfig(info *types.Info, collect func(error)) types.Config {
	sizes := types.SizesFor("gc", build.Default.GOARCH)
	return types.Config{
		Importer: l.importer,
		FakeImportC: true,
		Sizes: sizes,
		Error: func(err error) {
			if collect != nil {
				collect(err)
			}
		},
		_ = info,
	}
}

func (l *loader) checkDependency(lp *listPackage, imp *customImporter) *types.Package {
	key := cleanImportPath(lp.ImportPath)
	if p, ok := imp.cache[key]; ok {
		return p
	}
	if imp.inProgress == nil {
		imp.inProgress = map[string]bool{}
	}
	if imp.inProgress[key] {
		return types.NewPackage(key, lp.Name)
	}
	imp.inProgress[key] = true
	defer delete(imp.inProgress, key)
	filenames := l.filesFor(lp, true)
	files, _ := l.parseFiles(filenames)
	if len(files) == 0 && len(filenames) != 0 {
		return nil
	}
	sizes := types.SizesFor("gc", build.Default.GOARCH)
	conf := types.Config{Importer: imp, FakeImportC: true, Sizes: sizes, Error: func(error) {}}
	pkg, _ := conf.Check(key, l.fset, files, nil)
	if pkg != nil {
		imp.cache[key] = pkg
	}
	return pkg
}

func runGoList(patterns []string) ([]*listPackage, string) {
	if _, err := exec.LookPath("go"); err != nil {
		return nil, fmt.Sprintf("err: go command required, not found: %v: stderr: ", err)
	}
	args := []string{"list", "-e", "-json", fmt.Sprintf("-test=%v", flagTest), "-compiled=true", "-export=true", "-deps=true", "--"}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	err := cmd.Run()
	if err != nil {
		return nil, fmt.Sprintf("err: %v: stderr: %s", err, stderr.String())
	}
	var pkgs []*listPackage
	dec := json.NewDecoder(bytes.NewReader(stdout.Bytes()))
	idx := 0
	for dec.More() {
		var lp listPackage
		if err := dec.Decode(&lp); err != nil {
			return nil, fmt.Sprintf("err: %v: stderr: %s", err, stderr.String())
		}
		lp.index = idx
		idx++
		pkgs = append(pkgs, &lp)
	}
	return pkgs, ""
}

func isTestMainPackage(lp *listPackage) bool {
	return strings.HasSuffix(lp.ImportPath, ".test") && strings.HasSuffix(lp.ImportPath, ".test") && lp.ForTest == "" && len(lp.Match) == 0
}

func (l *loader) load(patterns []string) string {
	pkgs, fatal := runGoList(patterns)
	if fatal != "" {
		return fatal
	}
	l.pkgs = pkgs
	l.byPath = map[string]*listPackage{}
	l.byClean = map[string]*listPackage{}
	l.aliasTo = map[string]string{}
	for _, lp := range pkgs {
		if _, ok := l.byPath[lp.ImportPath]; !ok {
			l.byPath[lp.ImportPath] = lp
		}
		clean := cleanImportPath(lp.ImportPath)
		if _, ok := l.byClean[clean]; !ok {
			l.byClean[clean] = lp
		}
		for src, target := range lp.ImportMap {
			if _, ok := l.aliasTo[src]; !ok {
				l.aliasTo[src] = target
			}
		}
	}
	l.importer = &customImporter{fset: l.fset, loader: l, cache: map[string]*types.Package{}, inProgress: map[string]bool{}}
	l.importer.exportImp = importer.ForCompiler(l.fset, "gc", l.importer.lookup)

	// Determine roots in the order produced by go list.
	var lpRoots []*listPackage
	seenRoot := map[string]bool{}
	addRoot := func(lp *listPackage) {
		if lp == nil {
			return
		}
		key := lp.ImportPath
		if seenRoot[key] {
			return
		}
		// The generated test-main package is not an analysis root
		// unless it was matched explicitly.
		if isTestMainPackage(lp) {
			return
		}
		seenRoot[key] = true
		lpRoots = append(lpRoots, lp)
	}
	for _, lp := range pkgs {
		if len(lp.Match) > 0 {
			addRoot(lp)
		} else if lp.ForTest != "" {
			addRoot(lp)
		}
	}
	for _, lp := range lpRoots {
		rp := &rootPackage{lp: lp, key: lp.ImportPath, typesPath: cleanImportPath(lp.ImportPath)}
		l.roots = append(l.roots, rp)
		l.checkRoot(rp)
	}
	l.computeIllTyped()
	l.collectLoadErrors()
	return ""
}

func (l *loader) checkRoot(rp *rootPackage) {
	filenames := l.filesFor(rp.lp, true)
	files, perrs := l.parseFiles(filenames)
	rp.files = files
	rp.ownErrors = append(rp.ownErrors, perrs...)
	info := &types.Info{
		Types:      make(map[ast.Expr]types.TypeAndValue),
		Defs:       make(map[*ast.Ident]types.Object),
		Uses:       make(map[*ast.Ident]types.Object),
		Selections: make(map[*ast.SelectorExpr]*types.Selection),
	}
	rp.info = info
	if len(files) == 0 {
		// Packages such as unsafe and packages with load failures
		// have no syntax to check.  Give them an empty package so
		// the analyzer has a valid path to compare against.
		rp.typesPkg = types.NewPackage(rp.typesPath, rp.lp.Name)
		if len(rp.lp.ErrorString()) > 0 || rp.lp.Error != nil {
			rp.illTyped = true
		}
		return
	}
	sizes := types.SizesFor("gc", build.Default.GOARCH)
	conf := types.Config{
		Importer:    l.importer,
		FakeImportC: true,
		Sizes:       sizes,
		Error: func(err error) {
			if te, ok := err.(types.Error); ok {
				pos := l.fset.Position(te.Pos)
				rp.ownErrors = append(rp.ownErrors, pkgError{Pos: pos.String(), Msg: te.Msg})
			} else {
				rp.ownErrors = append(rp.ownErrors, pkgError{Msg: err.Error()})
			}
		},
	}
	pkg, _ := conf.Check(rp.typesPath, l.fset, files, info)
	rp.typesPkg = pkg
	if rp.typesPkg == nil {
		rp.typesPkg = types.NewPackage(rp.typesPath, rp.lp.Name)
	}
}

func (lp *listPackage) ErrorString() string {
	if lp.Error == nil {
		return ""
	}
	return lp.Error.Err
}

// reachable returns the set of list-package indices reachable from lp
// through its imports.
func (l *loader) reachable(lp *listPackage) map[int]bool {
	seen := map[int]bool{}
	var visit func(p *listPackage)
	visit = func(p *listPackage) {
		if p == nil || seen[p.index] {
			return
		}
		seen[p.index] = true
		for _, imp := range p.Imports {
			target := imp
			if p.ImportMap != nil {
				if mapped, ok := p.ImportMap[imp]; ok {
					target = mapped
				}
			}
			visit(l.findListPackage(target))
		}
	}
	visit(lp)
	return seen
}

func (l *loader) computeIllTyped() {
	for _, rp := range l.roots {
		if len(rp.ownErrors) > 0 {
			rp.illTyped = true
		}
		if rp.lp.Error != nil || len(rp.lp.DepsErrors) > 0 {
			rp.illTyped = true
		}
		reach := l.reachable(rp.lp)
		for idx := range reach {
			p := l.pkgs[idx]
			if p.Error != nil {
				rp.illTyped = true
				break
			}
		}
	}
}

func (l *loader) addLoadError(e pkgError) {
	key := e.Pos + "\x00" + strings.TrimRight(e.Msg, "\n")
	if l.seenLoadErr[key] {
		return
	}
	l.seenLoadErr[key] = true
	l.loadErrors = append(l.loadErrors, e)
}

func (l *loader) collectLoadErrors() {
	l.seenLoadErr = map[string]bool{}
	rootByIndex := map[int]*rootPackage{}
	for _, rp := range l.roots {
		rootByIndex[rp.lp.index] = rp
	}
	for _, lp := range l.pkgs {
		if lp.Error != nil {
			l.addLoadError(pkgError{Pos: lp.Error.Pos, Msg: lp.Error.Err})
		}
		for _, de := range lp.DepsErrors {
			if de != nil {
				l.addLoadError(pkgError{Pos: de.Pos, Msg: de.Err})
			}
		}
		if rp, ok := rootByIndex[lp.index]; ok {
			for _, e := range rp.ownErrors {
				// Errors that arise purely because an imported
				// package failed to load are already represented
				// by that package's load error; the equivalent
				// "could not import" failure for a package with a
				// genuine load error is suppressed.  Keep all
				// other type errors from the root itself.
				l.addLoadError(e)
			}
		}
	}
}

// ---------------- analyzer ----------------

type validatedConfig struct {
	ignoreSigs     []string
	ignoreSigRes   []*regexp.Regexp
	ignoreIfaceRes []*regexp.Regexp
	globs          []*globMatcher
}

func validateConfig(c *Config) (*validatedConfig, string) {
	v := &validatedConfig{ignoreSigs: c.IgnoreSigs}
	for _, pat := range c.IgnoreSigRegexps {
		re, err := regexp.Compile(pat)
		if err != nil {
			return nil, fmt.Sprintf("unable to compile regexp %s: %s\n", pat, err)
		}
		v.ignoreSigRes = append(v.ignoreSigRes, re)
	}
	for _, pat := range c.IgnoreInterfaceRegexps {
		re, err := regexp.Compile(pat)
		if err != nil {
			return nil, fmt.Sprintf("unable to compile regexp %s: %s\n", pat, err)
		}
		v.ignoreIfaceRes = append(v.ignoreIfaceRes, re)
	}
	for _, pat := range c.IgnorePackageGlobs {
		g, err := compileGlob(pat)
		if err != nil {
			var nilGlob *globMatcher
			_ = nilGlob
			return nil, fmt.Sprintf("unable to compile globs %s: %s\n", nilInterface(), err)
		}
		v.globs = append(v.globs, g)
	}
	return v, ""
}

func nilInterface() interface{} { return nil }

func isErrorType(t types.Type) bool {
	if t == nil {
		return false
	}
	if tuple, ok := t.(*types.Tuple); ok {
		for i := 0; i < tuple.Len(); i++ {
			if tuple.At(i).Type() != nil && tuple.At(i).Type().String() == "error" {
				return true
			}
		}
		return false
	}
	return t.String() == "error"
}

func exprIsError(info *types.Info, expr ast.Expr) bool {
	if info == nil || expr == nil {
		return false
	}
	return isErrorType(info.TypeOf(expr))
}

func identObject(info *types.Info, id *ast.Ident) types.Object {
	if info == nil || id == nil {
		return nil
	}
	if obj := info.Defs[id]; obj != nil {
		return obj
	}
	return info.Uses[id]
}

type analyzer struct {
	cfg  *Config
	vc   *validatedConfig
	root *rootPackage
	fset *token.FileSet
	out  []diagnostic
}

func (a *analyzer) reportf(pos token.Pos, format string, args ...interface{}) {
	position := a.fset.Position(pos)
	a.out = append(a.out, diagnostic{
		pos:     pos,
		posStr:  position.String(),
		file:    position.Filename,
		line:    position.Line,
		message: fmt.Sprintf(format, args...),
	})
}

func (a *analyzer) sigIgnored(sig string) bool {
	for _, s := range a.vc.ignoreSigs {
		if strings.Contains(sig, s) {
			return true
		}
	}
	for _, re := range a.vc.ignoreSigRes {
		if re.MatchString(sig) {
			return true
		}
	}
	return false
}

func (a *analyzer) ifaceIgnored(name string) bool {
	for _, re := range a.vc.ignoreIfaceRes {
		if re.MatchString(name) {
			return true
		}
	}
	return false
}

func (a *analyzer) checkCall(call *ast.CallExpr, diagPos token.Pos) {
	info := a.root.info
	if info == nil || call == nil {
		return
	}
	selExpr, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return
	}
	var obj types.Object
	var selection *types.Selection
	if sel, ok := info.Selections[selExpr]; ok {
		selection = sel
		obj = sel.Obj()
	} else if selExpr.Sel != nil {
		obj = info.ObjectOf(selExpr.Sel)
	}
	if obj == nil {
		return
	}
	switch obj.(type) {
	case *types.Func, *types.Var:
	default:
		return
	}
	sig := obj.String()
	if a.sigIgnored(sig) {
		return
	}
	objPkgPath := ""
	if obj.Pkg() != nil {
		objPkgPath = obj.Pkg().Path()
	}
	for _, g := range a.vc.globs {
		if g.Match(objPkgPath) {
			if a.cfg.ReportInternalErrors {
				a.reportf(diagPos, "package-internal error should be wrapped: sig: %s", sig)
			}
			return
		}
	}
	if selection != nil {
		recv := selection.Recv()
		if recv != nil {
			if _, isIface := recv.Underlying().(*types.Interface); isIface {
				ifaceName := types.TypeString(recv, func(p *types.Package) string {
					if p == nil {
						return ""
					}
					return p.Name()
				})
				if !a.ifaceIgnored(ifaceName) {
					a.reportf(diagPos, "error returned from interface method should be wrapped: sig: %s", sig)
					return
				}
			}
		}
	}
	currentPath := ""
	if a.root.typesPkg != nil {
		currentPath = a.root.typesPkg.Path()
	}
	if objPkgPath == currentPath {
		if a.cfg.ReportInternalErrors {
			a.reportf(diagPos, "package-internal error should be wrapped: sig: %s", sig)
		}
		return
	}
	a.reportf(diagPos, "error returned from external package is unwrapped: sig: %s", sig)
}

// findAssignment locates the last assignment (in source order) to the
// object denoted by target that begins before target, within file.  It
// returns the call expression from the right-hand side, or nil when the
// most recent assignment is not a call (or there is none).
func (a *analyzer) findAssignment(file *ast.File, target *ast.Ident) *ast.CallExpr {
	info := a.root.info
	targetObj := identObject(info, target)
	if targetObj == nil {
		return nil
	}
	var found *ast.CallExpr
	astInsp := func(n ast.Node) bool {
		if n == nil {
			return true
		}
		if n.Pos() > target.Pos() {
			return false
		}
		switch x := n.(type) {
		case *ast.AssignStmt:
			for _, lhs := range x.Lhs {
				lhsID, ok := lhs.(*ast.Ident)
				if !ok {
					continue
				}
				if identObject(info, lhsID) != targetObj {
					continue
				}
				if len(x.Rhs) > 0 {
					if call, ok := x.Rhs[0].(*ast.CallExpr); ok {
						found = call
					} else {
						found = nil
					}
				}
			}
		case *ast.ValueSpec:
			for _, name := range x.Names {
				if identObject(info, name) != targetObj {
					continue
				}
				if len(x.Values) > 0 {
					if call, ok := x.Values[0].(*ast.CallExpr); ok {
						found = call
					} else {
						found = nil
					}
				} else {
					found = nil
				}
			}
		}
		return true
	}
	_ = astInsp
	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			return true
		}
		return astInsp(n)
	})
	return found
}

func (a *analyzer) processReturn(ret *ast.ReturnStmt, file *ast.File, inFuncLit bool) {
	info := a.root.info
	for _, result := range ret.Results {
		switch expr := result.(type) {
		case *ast.CallExpr:
			if !inFuncLit && exprIsError(info, expr) {
				a.checkCall(expr, expr.Pos())
			}
			return
		case *ast.Ident:
			if !exprIsError(info, expr) {
				continue
			}
			call := a.findAssignment(file, expr)
			if call == nil {
				return
			}
			a.checkCall(call, expr.Pos())
			continue
		default:
			if exprIsError(info, result) {
				return
			}
			continue
		}
	}
}

func (a *analyzer) runFile(file *ast.File) {
	var stack []ast.Node
	ast.Inspect(file, func(n ast.Node) bool {
		if n == nil {
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			return true
		}
		inFuncLit := false
		for _, anc := range stack {
			if _, ok := anc.(*ast.FuncLit); ok {
				inFuncLit = true
				break
			}
		}
		if ret, ok := n.(*ast.ReturnStmt); ok {
			a.processReturn(ret, file, inFuncLit)
		}
		stack = append(stack, n)
		return true
	})
}

func runAnalyzerOnRoot(cfg *Config, vc *validatedConfig, rp *rootPackage, fset *token.FileSet) []diagnostic {
	a := &analyzer{cfg: cfg, vc: vc, root: rp, fset: fset}
	for _, f := range rp.files {
		a.runFile(f)
	}
	return a.out
}

// ---------------- output ----------------

type jsonDiag struct {
	Posn    string `json:"posn"`
	Message string `json:"message"`
}

type jsonValue struct {
	diags []jsonDiag
	err   string
	isErr bool
}

func (v jsonValue) MarshalJSON() ([]byte, error) {
	if v.isErr {
		return json.Marshal(struct {
			Error string `json:"error"`
		}{Error: v.err})
	}
	if v.diags == nil {
		return []byte("[]"), nil
	}
	return json.Marshal(v.diags)
}

var profileCPU, profileTrace, profileMem *os.File

func startProfiles() error {
	if flagCPUProfile != "" {
		f, err := os.Create(flagCPUProfile)
		if err != nil {
			return err
		}
		profileCPU = f
		if err := pprof.StartCPUProfile(f); err != nil {
			return err
		}
	}
	if flagTrace != "" {
		f, err := os.Create(flagTrace)
		if err != nil {
			return err
		}
		profileTrace = f
		if err := trace.Start(f); err != nil {
			return err
		}
	}
	if flagMemProfile != "" {
		f, err := os.Create(flagMemProfile)
		if err != nil {
			return err
		}
		profileMem = f
	}
	return nil
}

func stopProfiles() {
	if profileCPU != nil {
		pprof.StopCPUProfile()
		profileCPU.Close()
		profileCPU = nil
	}
	if profileTrace != nil {
		trace.Stop()
		profileTrace.Close()
		profileTrace = nil
		fmt.Fprintf(os.Stderr, "wrapcheck: To view the trace, run:\n$ go tool trace view %s\n", flagTrace)
	}
	if profileMem != nil {
		runtime.GC()
		_ = pprof.WriteHeapProfile(profileMem)
		profileMem.Close()
		profileMem = nil
	}
}

func main() {
	cfgGlobal = loadConfig()

	flag.Var(&flagVersion, "V", "print version and exit")
	flag.BoolVar(&flagAll, "all", false, "no effect (deprecated)")
	flag.IntVar(&flagC, "c", -1, "display offending line with this many lines of context")
	flag.StringVar(&flagCPUProfile, "cpuprofile", "", "write CPU profile to this file")
	flag.StringVar(&flagDebug, "debug", "", "debug flags, any subset of \"fpstv\"")
	flag.BoolVar(&flagDiff, "diff", false, "with -fix, don't update the files, but print a unified diff")
	flag.BoolVar(&flagFix, "fix", false, "apply all suggested fixes")
	flag.BoolVar(&flagFlags, "flags", false, "print analyzer flags in JSON")
	flag.BoolVar(&flagJSON, "json", false, "emit JSON output")
	flag.StringVar(&flagMemProfile, "memprofile", "", "write memory profile to this file")
	flag.BoolVar(&flagSource, "source", false, "no effect (deprecated)")
	flag.StringVar(&flagTags, "tags", "", "no effect (deprecated)")
	flag.BoolVar(&flagTest, "test", true, "indicates whether test files should be analyzed, too")
	flag.StringVar(&flagTrace, "trace", "", "write trace log to this file")
	flag.BoolVar(&flagV, "v", false, "no effect (deprecated)")
	flag.Usage = printUsage
	flag.Parse()

	// Version handling precedes the -flags handling.
	if flagVersion.set {
		if flagVersion.value != "full" {
			fmt.Fprintf(os.Stderr, "wrapcheck: unsupported flag value: -V=%s (use -V=full)\n", flagVersion.value)
			os.Exit(1)
		}
		exe, err := os.Executable()
		if err == nil {
			var info *debug.BuildInfo
			info, err = debug.ReadBuildInfoFromFile(exe)
			_ = info
			if err == nil {
				// placeholder replaced below
			}
		}
		// Use the build info of this executable.
		handleVersionFull()
		return
	}
	if flagFlags {
		printFlagsJSON()
		return
	}
	patterns := flag.Args()
	if len(patterns) == 0 {
		printUsage()
		os.Exit(1)
	}
	os.Exit(runMain(patterns))
}

func handleVersionFull() {
	exe, err := os.Executable()
	if err != nil {
		fmt.Fprintf(os.Stderr, "wrapcheck: %s\n", err)
		os.Exit(1)
	}
	info, err := readBuildInfoFile(exe)
	if err != nil {
		fmt.Fprintf(os.Stderr, "wrapcheck: %s\n", err)
		os.Exit(1)
	}
	fmt.Fprintln(os.Stdout, info)
	os.Exit(0)
}

var contextLinesCache = map[string][]string{}

func contextLines(filename string) []string {
	if lines, ok := contextLinesCache[filename]; ok {
		return lines
	}
	data, err := os.ReadFile(filename)
	if err != nil {
		contextLinesCache[filename] = nil
		return nil
	}
	lines := strings.Split(string(data), "\n")
	contextLinesCache[filename] = lines
	return lines
}

func debugEnabled(ch byte) bool {
	return strings.IndexByte(flagDebug, ch) >= 0
}

func runMain(patterns []string) int {
	if err := startProfiles(); err != nil {
		fmt.Fprintf(os.Stderr, "wrapcheck: %s\n", err)
		return 1
	}
	defer stopProfiles()

	verbose := flagV || debugEnabled('v')
	var logOut = log.New(os.Stderr, "", log.Ltime|log.Lmicroseconds)
	if verbose {
		logOut.Printf("load %v", patterns)
	}

	ldr := &loader{fset: token.NewFileSet()}
	if fatal := ldr.load(patterns); fatal != "" {
		msg := fatal
		fmt.Fprintf(os.Stderr, "wrapcheck: %s", msg)
		if !strings.HasSuffix(msg, "\n") {
			fmt.Fprintln(os.Stderr)
		}
		return 1
	}
	if verbose {
		logOut.Printf("building graph of analysis passes")
	}
	if len(ldr.roots) == 0 {
		fmt.Fprintf(os.Stderr, "wrapcheck: %s matched no packages\n", strings.Join(patterns, " "))
		return 1
	}

	// Package load errors are printed in every output mode.
	for _, e := range ldr.loadErrors {
		fmt.Fprintf(os.Stderr, "%s\n", e.String())
	}

	vc, analyzerErr := validateConfig(cfgGlobal)
	anyIll := false
	anyAnalyzerErr := false
	for _, rp := range ldr.roots {
		if rp.illTyped {
			rp.hasActionErr = true
			rp.actionErr = "analysis skipped due to errors in package"
			anyIll = true
			continue
		}
		if analyzerErr != "" {
			rp.hasActionErr = true
			rp.actionErr = analyzerErr
			anyAnalyzerErr = true
			continue
		}
		rp.diagnostics = runAnalyzerOnRoot(cfgGlobal, vc, rp, ldr.fset)
	}

	if flagFix {
		if anyIll {
			return 1
		}
		return 0
	}

	if flagJSON {
		results := map[string]map[string]jsonValue{}
		for _, rp := range ldr.roots {
			key := rp.key
			var val jsonValue
			if rp.hasActionErr {
				val = jsonValue{isErr: true, err: rp.actionErr}
			} else if len(rp.diagnostics) > 0 {
				val = jsonValue{}
				for _, d := range rp.diagnostics {
					val.diags = append(val.diags, jsonDiag{Posn: d.posStr, Message: d.message})
				}
			} else {
				continue
			}
			if results[key] == nil {
				results[key] = map[string]jsonValue{}
			}
			results[key]["wrapcheck"] = val
		}
		data, _ := json.MarshalIndent(results, "", "\t")
		os.Stdout.Write(data)
		os.Stdout.Write([]byte("\n"))
		if anyIll {
			return 1
		}
		return 0
	}

	// Plain mode: action errors first, then diagnostics in package
	// (dependency) order, de-duplicated across packages.
	for _, rp := range ldr.roots {
		if rp.hasActionErr {
			fmt.Fprintf(os.Stderr, "wrapcheck: %s\n", rp.actionErr)
		}
	}
	seenDiag := map[string]bool{}
	foundDiag := false
	for _, rp := range ldr.roots {
		for _, d := range rp.diagnostics {
			key := d.posStr + "\x00" + d.message
			if seenDiag[key] {
				continue
			}
			seenDiag[key] = true
			foundDiag = true
			fmt.Fprintf(os.Stderr, "%s: %s\n", d.posStr, d.message)
			if flagC >= 0 {
				lines := contextLines(d.file)
				if lines != nil {
					start := d.line - flagC
					if start < 1 {
						start = 1
					}
					end := d.line + flagC
					if end > len(lines) {
						end = len(lines)
					}
					for ln := start; ln <= end; ln++ {
						fmt.Fprintf(os.Stderr, "%d\t%s\n", ln, lines[ln-1])
					}
				}
			}
		}
	}
	if debugEnabled('t') {
		fmt.Fprintf(os.Stderr, "wrapcheck: Warning: times are mostly GC/scheduler noise; use -debug=tp to disable parallelism\n")
		for _, rp := range ldr.roots {
			fmt.Fprintf(os.Stderr, "%s\twrapcheck@%s\n", "0s", rp.key)
		}
	}
	if anyIll || anyAnalyzerErr {
		return 1
	}
	if foundDiag {
		return 3
	}
	// Ensure sorted keys behaviour in maps does not affect plain
	// mode (kept for parity with deterministic output).
	_ = sort.StringSlice{}
	return 0
}
GOEOF
echo done"}

