import pathlib
p=pathlib.Path('/workspace/main.go')
s=p.read_text()

# rootPackage: add all roots reference? Instead add roots to analyzer via function signature.
s=s.replace('''type analyzer struct {
	cfg  *Config
	vc   *validatedConfig
	root *rootPackage
	fset *token.FileSet
	out  []diagnostic
}''','''type analyzer struct {
	cfg   *Config
	vc    *validatedConfig
	root  *rootPackage
	roots []*rootPackage
	fset  *token.FileSet
	out   []diagnostic
}''')
s=s.replace('''func runAnalyzerOnRoot(cfg *Config, vc *validatedConfig, rp *rootPackage, fset *token.FileSet) []diagnostic {
	a := &analyzer{cfg: cfg, vc: vc, root: rp, fset: fset}''','''func runAnalyzerOnRoot(cfg *Config, vc *validatedConfig, rp *rootPackage, roots []*rootPackage, fset *token.FileSet) []diagnostic {
	a := &analyzer{cfg: cfg, vc: vc, root: rp, roots: roots, fset: fset}''')
s=s.replace('rp.diagnostics = runAnalyzerOnRoot(cfgGlobal, vc, rp, ldr.fset)','rp.diagnostics = runAnalyzerOnRoot(cfgGlobal, vc, rp, ldr.roots, ldr.fset)')

# Refactor checkCall object resolution into a helper and add alias-aware helpers before checkCall.
marker='''func (a *analyzer) checkCall(call *ast.CallExpr, diagPos token.Pos) {'''
helpers=r'''func (a *analyzer) callObject(call *ast.CallExpr) (types.Object, *types.Selection) {
	info := a.root.info
	if info == nil || call == nil {
		return nil, nil
	}
	selExpr, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return nil, nil
	}
	if sel, ok := info.Selections[selExpr]; ok {
		return sel.Obj(), sel
	}
	if selExpr.Sel != nil {
		return info.ObjectOf(selExpr.Sel), nil
	}
	return nil, nil
}

func receiverBaseName(t types.Type) string {
	for {
		if ptr, ok := t.(*types.Pointer); ok {
			t = ptr.Elem()
			continue
		}
		break
	}
	switch tt := t.(type) {
	case *types.Named:
		if tt.Obj() != nil {
			return tt.Obj().Name()
		}
	case *types.TypeParam:
		return tt.Obj().Name()
	}
	return ""
}

func syntacticBaseName(expr ast.Expr) string {
	switch e := expr.(type) {
	case *ast.Ident:
		return e.Name
	case *ast.SelectorExpr:
		return e.Sel.Name
	case *ast.StarExpr:
		return syntacticBaseName(e.X)
	case *ast.IndexExpr:
		return syntacticBaseName(e.X)
	case *ast.IndexListExpr:
		return syntacticBaseName(e.X)
	case *ast.ParenExpr:
		return syntacticBaseName(e.X)
	}
	return ""
}

func expandResultTypeExprs(results *ast.FieldList) []ast.Expr {
	if results == nil {
		return nil
	}
	var out []ast.Expr
	for _, field := range results.List {
		n := len(field.Names)
		if n == 0 {
			n = 1
		}
		for i := 0; i < n; i++ {
			out = append(out, field.Type)
		}
	}
	return out
}

func astTypeIsExactError(expr ast.Expr, info *types.Info) bool {
	switch e := expr.(type) {
	case *ast.Ident:
		if e.Name != "error" {
			return false
		}
		if info != nil {
			if obj := identObject(info, e); obj != nil {
				return obj == types.Universe.Lookup("error")
			}
		}
		return true
	case *ast.ParenExpr:
		return astTypeIsExactError(e.X, info)
	default:
		return false
	}
}

// sourceFuncResultTypes returns the result type expressions of the
// declaration of fn when that declaration is present in one of the
// packages being analysed from source.
