	for _, field := range results.List {
		n := len(field.Names)
		if n == 0 {
			n = 1
		}
		for i := 0; i < n; i++ {
			out = append(out, field.Type)
		}
	}
	return out
}

func astTypeIsExactError(expr ast.Expr, info *types.Info) bool {
	switch e := expr.(type) {
	case *ast.Ident:
		if e.Name != "error" {
			return false
		}
		if info != nil {
			if obj := identObject(info, e); obj != nil {
				return obj == types.Universe.Lookup("error")
			}
		}
		return true
	case *ast.ParenExpr:
		return astTypeIsExactError(e.X, info)
	default:
		return false
	}
}

// sourceFuncResultTypes returns the result type expressions of the
// declaration of fn when that declaration is present in one of the
// packages being analysed from source.
func (a *analyzer) sourceFuncResultTypes(fn *types.Func) ([]ast.Expr, *types.Info, bool) {
	if fn == nil || fn.Pkg() == nil {
		return nil, nil, false
	}
	path := fn.Pkg().Path()
	expectedRecv := ""
	if sig, ok := fn.Type().(*types.Signature); ok && sig != nil && sig.Recv() != nil {
		expectedRecv = receiverBaseName(sig.Recv().Type())
	}
	for _, candidate := range a.roots {
		if candidate == nil || candidate.typesPath != path {
			continue
		}
		for _, file := range candidate.files {
			var found []ast.Expr
			var foundInfo *types.Info
			ast.Inspect(file, func(n ast.Node) bool {
				if found != nil || n == nil {
					return true
				}
				if decl, ok := n.(*ast.FuncDecl); ok && decl.Name != nil && decl.Name.Name == fn.Name() {
					recv := ""
					if decl.Recv != nil && len(decl.Recv.List) > 0 {
						recv = syntacticBaseName(decl.Recv.List[0].Type)
					}
					if recv == expectedRecv && decl.Type != nil {
						found = expandResultTypeExprs(decl.Type.Results)
						foundInfo = candidate.info
					}
					return false
				}
				return true
			})
			if found != nil {
				return found, foundInfo, true
			}
			// Interface method declarations have no FuncDecl.
			var stack []ast.Node
			ast.Inspect(file, func(n ast.Node) bool {
				if n == nil {
					if len(stack) > 0 {
						stack = stack[:len(stack)-1]
					}
					return true
				}
				if found == nil {
					if field, ok := n.(*ast.Field); ok {
						if ft, ok := field.Type.(*ast.FuncType); ok {
							for _, name := range field.Names {
								if name.Name == fn.Name() {
									// Confirm the field is in an interface.
									for _, anc := range stack {
										if _, isIface := anc.(*ast.InterfaceType); isIface {
											found = expandResultTypeExprs(ft.Results)
											foundInfo = candidate.info
										}
									}
								}
							}
						}
					}
				}
				stack = append(stack, n)
				return true
			})
			if found != nil {
				return found, foundInfo, true
			}
		}
	}
	return nil, nil, false
}

func (a *analyzer) callResultIsError(call *ast.CallExpr, resultIndex *int) bool {
	var obj types.Object
	if ident, ok := call.Fun.(*ast.Ident); ok {
		if a.root.info != nil {
			obj = a.root.info.ObjectOf(ident)
		}
	} else {
		obj, _ = a.callObject(call)
	}
	if fn, ok := obj.(*types.Func); ok {
		if resultTypes, srcInfo, found := a.sourceFuncResultTypes(fn); found {
			if resultIndex != nil {
				if *resultIndex >= 0 && *resultIndex < len(resultTypes) {
					return astTypeIsExactError(resultTypes[*resultIndex], srcInfo)
				}
			} else {
				for _, rt := range resultTypes {
					if astTypeIsExactError(rt, srcInfo) {
						return true
					}
				}
				return false
			}
		}
	}
	return exprIsError(a.root.info, call)
}

func (a *analyzer) callIsError(call *ast.CallExpr) bool {
	return a.callResultIsError(call, nil)
}

type varDeclInfo struct {
	typeExpr ast.Expr
	rhs      ast.Expr
	rhsIndex int
	rhsFound bool
}

func (a *analyzer) findVarDecl(targetObj types.Object) (varDeclInfo, bool) {
	info := a.root.info
	var result varDeclInfo
	found := false
	for _, file := range a.root.files {
		if found {
			break
		}
		var stack []ast.Node
		ast.Inspect(file, func(n ast.Node) bool {
			if n == nil {
				if len(stack) > 0 {
					stack = stack[:len(stack)-1]
				}
				return true
			}
			if !found {
				if id, ok := n.(*ast.Ident); ok && info != nil && info.Defs[id] != nil && identObject(info, id) == targetObj {
					// Find the nearest relevant declaration ancestor.
					for i := len(stack) - 1; i >= 0; i-- {
						switch anc := stack[i].(type) {
						case *ast.Field:
							found = true
							result = varDeclInfo{typeExpr: anc.Type}
						case *ast.ValueSpec:
							found = true
							idx := 0
							for j, name := range anc.Names {
								if name == id {
									idx = j
									break
								}
							}
							if anc.Type != nil {
								result = varDeclInfo{typeExpr: anc.Type}
							} else if len(anc.Values) == 1 {
								result = varDeclInfo{rhs: anc.Values[0], rhsIndex: idx, rhsFound: true}
							} else if idx < len(anc.Values) {
								result = varDeclInfo{rhs: anc.Values[idx], rhsIndex: 0, rhsFound: true}
							}
						case *ast.AssignStmt:
							found = true
							idx := 0
							for j, lhs := range anc.Lhs {
								if lid, ok := lhs.(*ast.Ident); ok && lid == id {
									idx = j
									break
								}
							}
							if len(anc.Rhs) == 1 {
								result = varDeclInfo{rhs: anc.Rhs[0], rhsIndex: idx, rhsFound: true}
							} else if idx < len(anc.Rhs) {
								result = varDeclInfo{rhs: anc.Rhs[idx], rhsIndex: 0, rhsFound: true}
							}
						}
						if found {
							break
						}
					}
				}
			}
			stack = append(stack, n)
			return true
		})
	}
	return result, found
}

func (a *analyzer) identIsError(id *ast.Ident, visited map[types.Object]bool) bool {
	if !exprIsError(a.root.info, id) {
		return false
	}
	obj := identObject(a.root.info, id)
	if obj == nil {
		return true
	}
	if visited == nil {
		visited = map[types.Object]bool{}
	}
	if visited[obj] {
		return true
	}
	visited[obj] = true
	decl, found := a.findVarDecl(obj)
	if !found {
		return true
	}
	if decl.typeExpr != nil {
		return astTypeIsExactError(decl.typeExpr, a.root.info)
	}
	if decl.rhsFound && decl.rhs != nil {
		return a.derivedIsError(decl.rhs, decl.rhsIndex, visited)
	}
	return true
}

func (a *analyzer) derivedIsError(expr ast.Expr, index int, visited map[types.Object]bool) bool {
	switch e := expr.(type) {
	case *ast.CallExpr:
		if ident, ok := e.Fun.(*ast.Ident); ok {
			if obj := a.root.info.ObjectOf(ident); obj != nil {
				if _, isType := obj.(*types.TypeName); isType {
					return astTypeIsExactError(ident, a.root.info)
				}
			}
		}
		if sel, ok := e.Fun.(*ast.SelectorExpr); ok {
			if obj := a.root.info.ObjectOf(sel.Sel); obj != nil {
				if _, isType := obj.(*types.TypeName); isType {
					return false
				}
			}
		}
		idx := index
		return a.callResultIsError(e, &idx)
	case *ast.Ident:
		return a.identIsError(e, visited)
	case *ast.ParenExpr:
		return a.derivedIsError(e.X, index, visited)
	default:
		return exprIsError(a.root.info, expr)
	}
}

