					declSeen = true
					if len(vs.Values) > 0 {
						if call, ok := vs.Values[0].(*ast.CallExpr); ok {
							declCall = call
						} else {
							declCall = nil
						}
					} else {
						declCall = nil
					}
				}
			}
		}
		if n.Pos() > target.Pos() {
			return false
		}
