		case *ast.ValueSpec:
			for _, name := range x.Names {
				if identObject(info, name) != targetObj {
					continue
				}
				sawAssign = true
				if len(x.Values) > 0 {
					if call, ok := x.Values[0].(*ast.CallExpr); ok {
						found = call
					} else {
						found = nil
					}
				} else {
					found = nil
				}
			}
		}
		return true
	})
	if sawAssign {
		return found
	}
	if declSeen {
		return declCall
	}
	return nil
}

