		if err != nil || info.IsDir() || !strings.HasSuffix(fname, ".go") {
			// A file query that does not designate a Go file
			// contributes no packages.
			out = append(out, "example.invalid/file-query/...")
			continue
		}
		abs, err := filepath.Abs(fname)
		if err != nil {
