			for _, pat := range patterns {
				if pat == "." || strings.HasPrefix(pat, "./") || strings.HasPrefix(pat, "../") || (filepath.IsAbs(pat) && !strings.HasSuffix(pat, ".go")) {
					hasRelative = true
				}
				if !strings.HasSuffix(pat, ".go") {
					allGoFiles = false
				}
